{"implementation":"def solve(case):
    data = case.get("payload", case)
    nodes = data.get("nodes", [])
    required = set(data.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node.get("parent")
        if parent in children:
            children[parent].append(node["id"])

    symbol_counts = {}
    for node in nodes:
        symbol = node.get("symbol")
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1

    def subtree_ids(root_id):
        result = []
        stack = [root_id]
        while stack:
            node_id = stack.pop()
            result.append(node_id)
            stack.extend(children.get(node_id, ()))
        return result

    candidates = []
    for node in nodes:
        if not node.get("removable", False):
            continue
        removed = subtree_ids(node["id"])
        if any(not by_id[node_id].get("removable", False) for node_id in removed):
            continue
        removed_counts = {}
        for node_id in removed:
            symbol = by_id[node_id].get("symbol")
            removed_counts[symbol] = removed_counts.get(symbol, 0) + 1
        if any(symbol_counts.get(symbol, 0) - removed_counts.get(symbol, 0) <= 0 for symbol in required):
            continue
        loss = sum(float(by_id[node_id].get("utility", 0.0)) for node_id in removed)
        candidates.append((loss, -int(node.get("depth", 0)), node["id"]))

    if not candidates:
        return {"prune_id": None}
    candidates.sort()
    return {"prune_id": candidates[0][2]}
